 24→// TestDetectPresence uses t.Chdir so it cannot be parallel.
 25→func TestDetectPresence(t *testing.T) {
 26→	t.Run("factory directory exists", func(t *testing.T) {
 27→		tempDir := t.TempDir()
 28→		t.Chdir(tempDir)
 29→
 30→		if err := os.Mkdir(".factory", 0o755); err != nil {
 31→			t.Fatalf("failed to create .factory: %v", err)
 32→		}
 33→
 34→		ag := &FactoryAIDroidAgent{}
 35→		present, err := ag.DetectPresence()
 36→		if err != nil {
 37→			t.Fatalf("DetectPresence() error = %v", err)
 38→		}
