 90→func TestChunkTranscript_LargeContent(t *testing.T) {
 91→	t.Parallel()
 92→	ag := &FactoryAIDroidAgent{}
 93→
 94→	// Build multi-line JSONL that exceeds a small maxSize
 95→	var lines []string
 96→	for i := range 50 {
 97→		lines = append(lines, fmt.Sprintf(`{"role":"user","content":"message %d %s"}`, i, strings.Repeat("x", 200)))
 98→	}
 99→	content := []byte(strings.Join(lines, "\n"))
100→
101→	maxSize := 2000
102→	chunks, err := ag.ChunkTranscript(content, maxSize)
103→	if err != nil {
104→		t.Fatalf("ChunkTranscript() error = %v", err)
105→	}
106→	if len(chunks) < 2 {
107→		t.Errorf("Expected at least 2 chunks for large content, got %d", len(chunks))
108→	}
109→
110→	// Verify each chunk is valid JSONL (each line is valid JSON)
111→	for i, chunk := range chunks {
112→		chunkLines := strings.Split(string(chunk), "\n")
113→		for j, line := range chunkLines {
114→			if line == "" {
115→				continue
116→			}
117→			if line[0] != '{' {
118→				t.Errorf("Chunk %d, line %d doesn't look like JSON: %q", i, j, line[:min(len(line), 40)])
119→			}
120→		}
121→	}
122→}
