206→func TestReadSession(t *testing.T) {
207→	t.Parallel()
208→
209→	tmpDir := t.TempDir()
210→	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
211→
212→	// Write a Droid-format JSONL transcript with a file-modifying tool call
213→	content := `{"type":"message","id":"msg1","message":{"role":"user","content":[{"type":"text","text":"create a file"}]}}
214→{"type":"message","id":"msg2","message":{"role":"assistant","content":[{"type":"tool_use","name":"Write","input":{"file_path":"hello.txt","content":"hi"}}]}}`
215→	if err := os.WriteFile(transcriptPath, []byte(content), 0o644); err != nil {
216→		t.Fatalf("failed to write transcript: %v", err)
217→	}
218→
219→	ag := &FactoryAIDroidAgent{}
220→	session, err := ag.ReadSession(&agent.HookInput{
221→		SessionID:  "test-session-123",
222→		SessionRef: transcriptPath,
223→	})
224→	if err != nil {
225→		t.Fatalf("ReadSession() error = %v", err)
226→	}
227→
228→	if session.SessionID != "test-session-123" {
229→		t.Errorf("SessionID = %q, want %q", session.SessionID, "test-session-123")
230→	}
231→	if session.AgentName != agent.AgentNameFactoryAIDroid {
232→		t.Errorf("AgentName = %q, want %q", session.AgentName, agent.AgentNameFactoryAIDroid)
233→	}
234→	if session.SessionRef != transcriptPath {
235→		t.Errorf("SessionRef = %q, want %q", session.SessionRef, transcriptPath)
236→	}
237→	if len(session.NativeData) == 0 {
238→		t.Error("NativeData should not be empty")
239→	}
240→	if len(session.ModifiedFiles) == 0 {
241→		t.Error("ModifiedFiles should contain at least one file")
242→	}
243→}
