340→func TestReadWriteSession_RoundTrip(t *testing.T) {
341→	t.Parallel()
342→
343→	tmpDir := t.TempDir()
344→	originalPath := filepath.Join(tmpDir, "original.jsonl")
345→	restoredPath := filepath.Join(tmpDir, "restored.jsonl")
346→
347→	content := `{"type":"message","id":"msg1","message":{"role":"user","content":[{"type":"text","text":"hello"}]}}
348→{"type":"message","id":"msg2","message":{"role":"assistant","content":[{"type":"text","text":"hi there"}]}}`
349→	if err := os.WriteFile(originalPath, []byte(content), 0o644); err != nil {
350→		t.Fatalf("failed to write original: %v", err)
351→	}
352→
353→	ag := &FactoryAIDroidAgent{}
354→
355→	// Read from original location
356→	session, err := ag.ReadSession(&agent.HookInput{
357→		SessionID:  "round-trip-test",
358→		SessionRef: originalPath,
359→	})
360→	if err != nil {
361→		t.Fatalf("ReadSession() error = %v", err)
362→	}
363→
364→	// Write to new location
365→	session.SessionRef = restoredPath
366→	if err := ag.WriteSession(session); err != nil {
367→		t.Fatalf("WriteSession() error = %v", err)
368→	}
369→
370→	// Verify content matches
371→	restored, err := os.ReadFile(restoredPath)
372→	if err != nil {
373→		t.Fatalf("failed to read restored: %v", err)
374→	}
375→	if string(restored) != content {
376→		t.Errorf("round-trip mismatch:\n got: %q\nwant: %q", string(restored), content)
377→	}
