 593→func TestCalculateTotalTokenUsageFromTranscript_PerCheckpoint(t *testing.T) {
 594→	t.Parallel()
 595→
 596→	tmpDir := t.TempDir()
 597→	transcriptPath := tmpDir + "/transcript.jsonl"
 598→
 599→	// Build transcript with 3 turns:
 600→	// Turn 1: user + assistant (100 input, 50 output)
 601→	// Turn 2: user + assistant (200 input, 100 output)
 602→	// Turn 3: user + assistant (300 input, 150 output)
 603→	//
 604→	// Lines:
 605→	// 0: user message 1
 606→	// 1: assistant response 1 (100/50 tokens)
 607→	// 2: user message 2
 608→	// 3: assistant response 2 (200/100 tokens)
 609→	// 4: user message 3
 610→	// 5: assistant response 3 (300/150 tokens)
 611→
 612→	// Droid format: outer type is always "message", role is inside the inner message
 613→	transcriptContent := []byte(
 614→		`{"type":"message","id":"u1","message":{"role":"user","content":"first prompt"}}` + "\n" +
 615→			`{"type":"message","id":"a1","message":{"role":"assistant","id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
 616→			`{"type":"message","id":"u2","message":{"role":"user","content":"second prompt"}}` + "\n" +
 617→			`{"type":"message","id":"a2","message":{"role":"assistant","id":"m2","usage":{"input_tokens":200,"output_tokens":100}}}` + "\n" +
 618→			`{"type":"message","id":"u3","message":{"role":"user","content":"third prompt"}}` + "\n" +
 619→			`{"type":"message","id":"a3","message":{"role":"assistant","id":"m3","usage":{"input_tokens":300,"output_tokens":150}}}` + "\n",
 620→	)
 621→	if err := os.WriteFile(transcriptPath, transcriptContent, 0o600); err != nil {
 622→		t.Fatalf("failed to write transcript: %v", err)
 623→	}
 624→
 625→	// Test 1: From line 0 - all 3 turns = 600 input, 300 output
 626→	usage1, err := CalculateTotalTokenUsageFromTranscript(transcriptPath, 0, "")
 627→	if err != nil {
 628→		t.Fatalf("CalculateTotalTokenUsageFromTranscript(0) error: %v", err)
 629→	}
 630→	if usage1.InputTokens != 600 || usage1.OutputTokens != 300 {
 631→		t.Errorf("From line 0: got input=%d output=%d, want input=600 output=300",
 632→			usage1.InputTokens, usage1.OutputTokens)
 633→	}
 634→	if usage1.APICallCount != 3 {
 635→		t.Errorf("From line 0: got APICallCount=%d, want 3", usage1.APICallCount)
 636→	}
 637→
 638→	// Test 2: From line 2 (after turn 1) - turns 2+3 only = 500 input, 250 output
 639→	usage2, err := CalculateTotalTokenUsageFromTranscript(transcriptPath, 2, "")
 640→	if err != nil {
 641→		t.Fatalf("CalculateTotalTokenUsageFromTranscript(2) error: %v", err)
 642→	}
 643→	if usage2.InputTokens != 500 || usage2.OutputTokens != 250 {
 644→		t.Errorf("From line 2: got input=%d output=%d, want input=500 output=250",
 645→			usage2.InputTokens, usage2.OutputTokens)
 646→	}
 647→	if usage2.APICallCount != 2 {
 648→		t.Errorf("From line 2: got APICallCount=%d, want 2", usage2.APICallCount)
 649→	}
 650→
 651→	// Test 3: From line 4 (after turns 1+2) - turn 3 only = 300 input, 150 output
 652→	usage3, err := CalculateTotalTokenUsageFromTranscript(transcriptPath, 4, "")
 653→	if err != nil {
 654→		t.Fatalf("CalculateTotalTokenUsageFromTranscript(4) error: %v", err)
 655→	}
 656→	if usage3.InputTokens != 300 || usage3.OutputTokens != 150 {
 657→		t.Errorf("From line 4: got input=%d output=%d, want input=300 output=150",
 658→			usage3.InputTokens, usage3.OutputTokens)
 659→	}
 660→	if usage3.APICallCount != 1 {
 661→		t.Errorf("From line 4: got APICallCount=%d, want 1", usage3.APICallCount)
 662→	}
 663→}
